#!/usr/bin/env bash
# Brings upstream feedstock updates (conda-smithy, CI scripts) into the
# qt6-opcua branches:
#
#   main      mirror of conda-forge/packaging-feedstock, never committed to.
#             Update it with "Sync fork" on GitHub, or: gh repo sync --branch main
#   qt6-opcua shared changes on top of main: recipe/, conda-forge.yml and the
#             workflows in .github that conda-smithy does not generate
#   6.x.y     one per qt6-main version, qt6-opcua plus the version context in
#             recipe/recipe.yaml
#
# Usage: .github/scripts/sync-upstream.sh [upstream-ref]   (default origin/main)
#
# Merges upstream-ref into qt6-opcua, keeping our recipe/ and regenerating the
# conda-smithy files, then merges qt6-opcua into every 6.x.y branch. Nothing
# is pushed, check the result and push with:
#   git push origin qt6-opcua $(git for-each-ref --format='%(refname:short)' 'refs/heads/6.*')
set -euo pipefail

upstream=${1:-origin/main}
base=qt6-opcua

cd "$(git rev-parse --show-toplevel)"
if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
    echo "The working tree has uncommitted changes" >&2
    exit 1
fi
git fetch origin

git switch "$base"
if ! git merge --no-edit --no-commit "$upstream"; then
    for file in $(git diff --name-only --diff-filter=U); do
        case "$file" in
            recipe/*) ;;
            conda-forge.yml)
                echo "Resolve conda-forge.yml, then rerun the rest of this script by hand" >&2
                exit 1 ;;
            # Generated by conda-smithy, the rerender below rewrites it
            *) git checkout --theirs -- "$file" && git add -- "$file" ;;
        esac
    done
fi
# The upstream recipe is a different package, keep ours
git diff --cached --name-only --diff-filter=A HEAD -- recipe | while read -r file; do
    git rm -q -f -- "$file"
done
git checkout HEAD -- recipe

pixi exec -s conda-smithy -- conda-smithy rerender --no-check-uptodate
git add -u
if git rev-parse -q --verify MERGE_HEAD >/dev/null; then
    git commit --no-edit
elif ! git diff --cached --quiet; then
    git commit -m "MNT: Re-rendered with conda-smithy"
fi

for branch in $(git for-each-ref --format='%(refname:short)' 'refs/heads/6.*'); do
    git switch "$branch"
    git merge --no-edit "$base"
done
git switch "$base"
